        25: 283,
    },
    # Towers that can cover each area.  Areas 0 and 1 are given explicitly;
    # the remaining areas are represented by the full tower set so that the
    # model remains well-defined and constructible.
    "coverage": {
        0: [1, 5, 10, 11, 13, 15, 18, 19, 20, 22, 23, 24],
        1: [3, 4, 6, 11, 12, 14, 15, 17, 18, 19, 21, 23, 24],
    },
