# Fill in any area not explicitly listed with the full tower set.
for _a in range(DATA["num_areas"]):
    if _a not in DATA["coverage"]:
        DATA["coverage"][_a] = list(range(DATA["num_towers"]))


def build_model(data=None):
    d = data or DATA

    towers = list(range(d["num_towers"]))
    areas = list(range(d["num_areas"]))

    model = pyo.ConcreteModel()

    model.TOWERS = pyo.Set(initialize=towers, ordered=True)
    model.AREAS = pyo.Set(initialize=areas, ordered=True)

    model.build = pyo.Var(model.TOWERS, within=pyo.Binary)
    model.cover = pyo.Var(model.AREAS, within=pyo.Binary)

    population = d["population"]

    def obj_rule(m):
        return sum(population[a] * m.cover[a] for a in m.AREAS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    cost = d["cost"]

    def budget_rule(m):
        return sum(cost[t] * m.build[t] for t in m.TOWERS) <= d["budget"]

    model.budget = pyo.Constraint(rule=budget_rule)

    coverage = d["coverage"]

    def cover_link_rule(m, a):
        return m.cover[a] <= sum(m.build[t] for t in coverage[a])

    model.cover_link = pyo.Constraint(model.AREAS, rule=cover_link_rule)

    return model
